// Search a bounded character range, returning the offset or npos.

#include <stl/_algo.h>
#include <stl/_ctraits_fns.h>
#include <stl/char_traits.h>

struct BfmeRangePE
{
	char *m_bfmeAt;				// 0x0
	char *m_bfmeEnd;			// 0x4
};

class BfmeThingPE
{
public:
	void bfmeGoPE(const BfmeRangePE *span, void *what);

	unsigned int bfmeDoPE(const char *at, unsigned int what, unsigned int many);

	const char *m_bfmeAt;
	const char *m_bfmeEnd;
};

void BfmeThingPE::bfmeGoPE(const BfmeRangePE *span, void *what)
{
	bfmeDoPE(span->m_bfmeAt, (unsigned int)what,
		(unsigned int)(span->m_bfmeEnd - span->m_bfmeAt));
}

#pragma optimize("gty", on)
unsigned int BfmeThingPE::bfmeDoPE(const char *at, unsigned int what,
	unsigned int many)
{
	const unsigned int npos = (unsigned int)-1;
	const char *first = m_bfmeAt;
	const char *last = m_bfmeEnd;
	if (what + many <= (unsigned int)(last - first))
	{
		const char *p = _STL::search(first + what, last, at, at + many,
			_STL::_Eq_traits<_STL::char_traits<char> >());
		return p != last ? (unsigned int)(p - first) : npos;
	}
	return npos;
}
#pragma optimize("", off)
